// Chunked sparse voxel storage: 16×16 chunk columns of 16³ sections (uniform or paletted
// through a world-global state table), lazily generated by the TerrainGen.
import { MIN_Y, MAX_Y, TerrainGen } from './terrain.ts';

export const SECTIONS = (MAX_Y - MIN_Y + 1) >> 4; // 24
const AIR = 'minecraft:air';

/** a section is either a uniform state id or a dense Uint16Array(4096) of state ids */
export type Section = number | Uint16Array;

export interface Chunk {
  cx: number;
  cz: number;
  sections: Section[];
  /** bitmask of sections modified after generation (persisted on save) */
  dirty: number;
}

export const chunkKey = (cx: number, cz: number) => (cx + 0x100000) * 0x200000 + (cz + 0x100000);

export class World {
  readonly states: string[] = [AIR];
  private ids = new Map<string, number>([[AIR, 0]]);
  readonly chunks = new Map<number, Chunk>();
  readonly gen: TerrainGen;
  private lastKey = NaN;
  private lastChunk: Chunk | null = null;
  private generating = false;

  constructor(gen: TerrainGen) {
    this.gen = gen;
  }

  id(state: string): number {
    let i = this.ids.get(state);
    if (i === undefined) {
      i = this.states.length;
      if (i > 0xffff) throw new RangeError('simulation state table overflow (65536 states)');
      this.states.push(state);
      this.ids.set(state, i);
    }
    return i;
  }

  chunk(cx: number, cz: number): Chunk {
    const k = chunkKey(cx, cz);
    if (k === this.lastKey && this.lastChunk) return this.lastChunk;
    let c = this.chunks.get(k);
    if (!c) {
      c = { cx, cz, sections: new Array(SECTIONS).fill(0), dirty: 0 };
      this.chunks.set(k, c);
      this.generate(c);
    }
    this.lastKey = k;
    this.lastChunk = c;
    return c;
  }

  peekChunk(cx: number, cz: number): Chunk | undefined {
    return this.chunks.get(chunkKey(cx, cz));
  }

  private generate(c: Chunk): void {
    const was = this.generating;
    this.generating = true;
    const x0 = c.cx * 16, z0 = c.cz * 16;
    const put = (x: number, y: number, z: number, s: string) => {
      if (y < MIN_Y || y > MAX_Y) return;
      this.writeIn(c, x - x0, y - MIN_Y, z - z0, this.id(s));
    };
    const get = (x: number, y: number, z: number) => {
      if (y < MIN_Y || y > MAX_Y) return AIR;
      return this.states[this.readIn(c, x - x0, y - MIN_Y, z - z0)];
    };
    this.gen.generateChunk(c.cx, c.cz, put, get);
    // compact uniform sections
    for (let s = 0; s < SECTIONS; s++) {
      const sec = c.sections[s];
      if (typeof sec === 'number') continue;
      const v = sec[0];
      let uniform = true;
      for (let i = 1; i < 4096; i++) if (sec[i] !== v) { uniform = false; break; }
      if (uniform) c.sections[s] = v;
    }
    c.dirty = 0;
    this.generating = was;
  }

  /** local coords: lx,lz 0..15, ly 0..383 */
  readIn(c: Chunk, lx: number, ly: number, lz: number): number {
    const sec = c.sections[ly >> 4];
    if (typeof sec === 'number') return sec;
    return sec[((ly & 15) << 8) | (lz << 4) | lx];
  }

  writeIn(c: Chunk, lx: number, ly: number, lz: number, id: number): number {
    const si = ly >> 4;
    let sec = c.sections[si];
    if (typeof sec === 'number') {
      if (sec === id) return id;
      const arr = new Uint16Array(4096);
      if (sec !== 0) arr.fill(sec);
      c.sections[si] = sec = arr;
    }
    const i = ((ly & 15) << 8) | (lz << 4) | lx;
    const prev = sec[i];
    sec[i] = id;
    if (!this.generating) c.dirty |= 1 << si;
    return prev;
  }

  getId(x: number, y: number, z: number): number {
    if (y < MIN_Y || y > MAX_Y) return 0;
    const c = this.chunk(x >> 4, z >> 4);
    return this.readIn(c, x & 15, y - MIN_Y, z & 15);
  }

  get(x: number, y: number, z: number): string {
    return this.states[this.getId(x, y, z)];
  }

  /** set by id, returns previous id */
  setId(x: number, y: number, z: number, id: number): number {
    const c = this.chunk(x >> 4, z >> 4);
    return this.writeIn(c, x & 15, y - MIN_Y, z & 15, id);
  }
}
